function sumMoney(values){const present=values.filter(value=>value!=null);if(!present.length)return null;const scale=6n,factor=10n**scale,total=present.reduce((sum,value)=>{const text=String(value),negative=text.startsWith('-'),[whole,fraction='']=text.replace('-','').split('.'),scaled=BigInt(whole)*factor+BigInt(fraction.padEnd(Number(scale),'0').slice(0,Number(scale)));return sum+(negative?-scaled:scaled);},0n);const negative=total<0n,absolute=negative?-total:total,whole=absolute/factor,fraction=(absolute%factor).toString().padStart(Number(scale),'0').replace(/0+$/,'').padEnd(2,'0');return `${negative?'-':''}${whole}.${fraction}`;}

function decimalFromMillionths(value) {
  const whole = value / 1000000n;
  const fraction = String(value % 1000000n).padStart(6, '0').replace(/0+$/, '');
  return fraction ? `${whole}.${fraction}` : String(whole);
}

export function calculateProductGeometry(widthMm, heightMm, quantity) {
  if (![widthMm, heightMm, quantity].every(Number.isSafeInteger) || widthMm <= 0 || heightMm <= 0 || quantity <= 0) throw Object.assign(new Error('Invalid product geometry.'), { code: 'invalid_geometry' });
  return {
    areaSquareMetres: decimalFromMillionths(BigInt(widthMm) * BigInt(heightMm) * BigInt(quantity)),
    framePerimeterMetres: decimalFromMillionths(2n * BigInt(widthMm + heightMm) * BigInt(quantity) * 1000n),
  };
}

