const estimatePositionMap = (row) => {const source=parseJson(row.source_snapshot_json),geometry=calculateProductGeometry(row.width_mm,row.height_mm,row.quantity);return {id:row.id,scenarioId:row.scenario_id,estimatePositionId:row.estimate_position_id,sourceRowId:null,sourceSnapshot:source,evidenceOrigin:'estimate',displayReference:row.display_reference,productClass:row.product_class,quantity:row.quantity,widthMm:row.width_mm,heightMm:row.height_mm,installationOpeningCount:null,unitSupplyCost:null,totalPrice:null,currency:'GBP',classification:row.classification||'standard',includedInCurrentEstimate:Boolean(row.included_in_current_estimate),alternativeTo:row.alternative_to_reference,markupOverridePercent:row.markup_override_percent,sourceSequence:row.source_sequence,...geometry};};
